from pathlib import Path
import re, json, sys

ROOT=Path(__file__).resolve().parents[1]

def read(path): return (ROOT/path).read_text()
def write(path,text): (ROOT/path).write_text(text)
def replace(path,old,new,count=None):
    text=read(path)
    found=text.count(old)
    if found==0:
        raise SystemExit(f'guard failed: {path}: pattern not found: {old[:120]!r}')
    if count is not None and found!=count:
        raise SystemExit(f'guard failed: {path}: expected {count} occurrences, found {found}: {old[:120]!r}')
    text=text.replace(old,new)
    write(path,text)
    print(f'patched {path}: {found} occurrence(s)')

def insert_before(path,needle,addition):
    text=read(path)
    if needle not in text: raise SystemExit(f'guard failed: {path}: insertion anchor missing')
    text=text.replace(needle,addition+needle,1)
    write(path,text)
    print(f'inserted into {path}')

def require(path,needle):
    if needle not in read(path): raise SystemExit(f'required postcondition missing: {path}: {needle}')

def forbid(path,needle):
    if needle in read(path): raise SystemExit(f'forbidden postcondition present: {path}: {needle}')

